def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'D'
    if n == 99:
        return 'D'

    my_prev, opp_prev = history[-1]

    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

    r5 = history[-5:] if n >= 5 else history
    r10 = history[-10:] if n >= 10 else history
    r5_d = sum(1 for a, b in r5 if b == 'D')
    r10_d = sum(1 for a, b in r10 if b == 'D')

    o_d_streak = 0
    for a, b in reversed(history):
        if b == 'D':
            o_d_streak += 1
        else:
            break

    o_c_streak = 0
    for a, b in reversed(history):
        if b == 'C':
            o_c_streak += 1
        else:
            break

    resp = 0
    punish = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            resp += 1
            if history[i][1] == 'D':
                punish += 1

    forg = resp - punish
    forg_rate = float(forg) / float(resp) if resp else 0.0

    if opp_d * 10 > n * 6 or r5_d >= 4 or (opp_d * 2 > n and r10_d >= 5):
        if o_c_streak >= 5 and my_prev == 'C' and r5_d <= 1:
            return 'C'
        return 'D'

    if my_prev == 'D' and opp_prev == 'D':
        if opp_d * 4 >= n * 3 or o_d_streak >= 5:
            return 'D'
        if r5_d <= 2 or forg_rate >= 0.5:
            return 'C'
        if opp_d <= 3 and my_d <= 3:
            return 'C'
        return 'D'

    if opp_prev == 'D':
        return 'D'

    if opp_d <= max(2, n // 5):
        if resp >= 3 and punish == 0:
            if rng.random() < 0.80:
                return 'D'
            return 'C'
        if resp >= 1 and punish == 0 and forg_rate >= 0.90:
            if n < 95 and rng.random() < 0.55:
                return 'D'
            return 'C'
        if resp >= 2 and forg_rate >= 0.70:
            if n < 90 and rng.random() < 0.25:
                return 'D'
        return 'C'

    if resp >= 3 and forg_rate >= 0.75 and opp_d <= n * 0.45:
        if n < 90 and rng.random() < 0.12:
            return 'D'

    return 'C'
